import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1795299179000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><p>本页记录各版本中使用者与运维可感知的变化，每条标注 <strong>新增 / 修复 / 优化 / 调整</strong> 类别，适用于评估与升级版本的读者；仓库自身的 CI、测试与构建脚本不列入。</p><h2 id="未发布" tabindex="-1">未发布 <a class="header-anchor" href="#未发布" aria-label="Permalink to “未发布”">​</a></h2><ul><li><strong>新增</strong> 后端镜像随版本发布：每个版本标签都构建后端镜像推到 <code>ghcr.io/xihanfun/xihan-basicapp</code>，tag 是版本号（正式版另有 <code>latest</code>，只有 <code>linux/amd64</code>），docker compose 部署可以直接拉取，不用本地构建（见<a href="./deployment#容器-docker-compose">部署</a>）</li><li><strong>调整</strong> 顶栏上下文切换钮在平台一侧改用短文案（英文为 Platform Admin，西、法、葡、俄、日文只写「平台」），长文本语言下不再截断；控制中心切换页的标题仍是全称</li></ul><h2 id="v6-0-0-preview-3-2026-11-22" tabindex="-1">v6.0.0-preview.3 (2026-11-22) <a class="header-anchor" href="#v6-0-0-preview-3-2026-11-22" aria-label="Permalink to “v6.0.0-preview.3 (2026-11-22)”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，正式版前配置与表结构仍可能调整；接口方面，核心包的操作从这一版起定为稳定（见「调整」），可选模块的操作仍是预览。</li><li>后端依赖 XiHan.Framework 5.0.0-rc.6，前端依赖 XiHan.UI 5.7.0。</li><li><strong>按 preview.2 及之前建的库要新建</strong>：表结构改由 ORM 按实体补齐后，这类库升级时不报错，但改了名的表与列（OAuth 的 <code>sys_o_auth_*</code> 改为 <code>sys_oauth_*</code>，代码生成列配置的 <code>c_sharp_type</code>、<code>c_sharp_property</code> 改为 <code>csharp_type</code>、<code>csharp_property</code>）会建成空的新表、新列，原有的数据不再读到，旧表旧列留在库里；会话改按账号的安全戳核对，已登录的要重新登录。开发环境删掉库直接启动即可（自动建库、建表、播种）。</li><li><strong>结构版本升到 6.0.1，升级前先备份</strong>：台账推进到 6.0.1 之后，旧版本的程序再连这个库即 <code>RUNTIME_VALIDATION_004</code>，要回退只能还原备份；升级前可以先用新程序跑一次 <code>schema plan</code> 只读预览。把新版本覆盖到旧的发布目录（或 <code>BasicApp:Schema:Directory</code> 指向的目录）时先删掉 <code>Schema/6.0.0/</code>，留下的 <code>0001-baseline.sql</code> 会让升级以 <code>RUNTIME_VALIDATION_003</code> 失败；用镜像部署的不受影响。</li><li><strong>租户独立库升级失败不再中断启动</strong>：监控要看健康项 <code>basicapp.schema</code>（降级时就绪探针照样通过）与租户调用的 503 <code>RUNTIME_UNAVAILABLE_007</code>，修好后在版本管理页「重试升级」；部署脚本里 <code>schema upgrade</code> 以失败退出时，平台库可能已经升完。</li><li><strong>去掉的配置项</strong>，从 appsettings 与环境变量里删掉，它们不再生效：<code>BasicApp:Auth:PasswordMinLength</code> 与 <code>PasswordHistoryDepth</code>（改在系统参数 <code>identity.password</code> 里设）；<code>BasicApp:Notification:Brand</code>（系统名改在站点设置里填）；<code>XiHan:Security:Database:CacheSize</code>、<code>XiHan:MultiTenancy:Database:CacheSize</code>、<code>XiHan:MultiTenancy:ShardCacheSize</code>、<code>XiHan:MultiTenancy:ShardCacheTimeToLiveSeconds</code>、<code>XiHan:MultiTenancy:Database:MaxListedTenants</code>（缓存容量改看 <code>XiHan:Caching:InMemory:MaxEntries</code> / <code>Hybrid:LocalCapacity</code>）；前端的 <code>VITE_APP_TITLE</code>、<code>VITE_APP_SUBTITLE</code>、<code>VITE_APP_DESCRIPTION</code>、<code>VITE_APP_LOGO</code> 不再读取，改在站点设置里填。<code>XiHan:Security:Database:CacheTimeToLiveSeconds</code> 与 <code>XiHan:MultiTenancy:Database:CacheTimeToLiveSeconds</code> 必须为正，写成 <code>0</code> 启动即失败。</li><li><strong>新权限码只在首次播种时写入套餐与角色</strong>：<code>chat.chat-calls.read</code> / <code>call</code>、<code>settings.site.read</code> / <code>update</code>、<code>openplatform.oauth-signing-keys.read</code> / <code>rotate</code> / <code>retire</code>、<code>maintenance.versions.upgrade</code> / <code>release-lock</code>。新建的库不用动；没有新建库的，在套餐页与角色页授予（平台的 <code>*</code> 不用动）。</li><li><strong>接口变化</strong>：<code>chat-messages.forward</code> 的 <code>messageId</code> 改为 <code>messageIds</code>（同一个会话里的一条或多条）；<code>migrations.get</code> 的响应改为 <code>{ migration, sqlText }</code>，请求多了查询参数 <code>database</code>（不给为平台库）；<code>tenants.update</code> 整体覆盖新字段 <code>domain</code>，不带即解绑自定义域名；<code>menus.create</code> / <code>update</code> 的 <code>externalUrl</code> 上限由 1024 收到 512 个字符。</li><li><strong>二次开发要跟着改</strong>：实体上的 <code>[ActiveUniqueIndex]</code> 删除，改用框架的 <code>[EntityIndex(…, IsUnique = true, Name = …)]</code>，preview.2 代码生成出的实体写成 <code>Name = &quot;ux_&lt;表&gt;_tenant_id_&lt;列&gt;&quot;</code> 即与原来的索引名相同、库不用动；前端调用缺省 60 秒超时，自己页面里跑得久的调用传 <code>{ timeoutMs: LONG_TIMEOUT_MS }</code>（<code>~/request</code>）；<code>XEditModal</code> 与 <code>XContentEditorField</code> 的 <code>width</code> 只收档名 <code>sm</code>…<code>7xl</code>（缺省 <code>3xl</code>），原来传数字或 <code>760px</code> 的类型检查会报错；<code>XFileRefUpload</code> 的 <code>kind=&quot;file&quot;</code> 缺省不再限 10MB，以 <code>BasicApp:Files:MaxUploadBytes</code> 为准，要保留前端限制的写 <code>:max-size-mb=&quot;10&quot;</code>。</li><li><strong>S3 兼容存储的桶要给前端的来源放行跨域 <code>GET</code></strong>：除了预览，下载前也会跨域取签名地址探一下，没放行时下载提示文件暂时无法下载。</li><li>偏好里的「显示版权信息」换了存储键，之前关掉版权信息的要再关一次。</li></ul></div><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to “新增”">​</a></h3><ul><li><strong>新增</strong> 支持 MySQL 与 SQL Server：平台库和租户独立库都能用，<code>XiHan:Bindings:db</code> 的 <code>provider</code> 写 <code>mysql</code> 或 <code>sqlserver</code>（也认 <code>mssql</code>），独立库的库类型可以与平台库不同。MySQL 要 8.0.13 及以上、字符集 utf8mb4，软删除实体的唯一索引建成函数索引；SQL Server 实测 2022，库要打开 <code>READ_COMMITTED_SNAPSHOT</code>（还没有表的新库由结构升级打开，已有表的库没打开即升级失败），字符串建成 <code>nvarchar</code>。字符串长度按字符计；关键字搜索的大小写随库的排序规则（MySQL、SQL Server 缺省不区分）；<code>BasicApp:Schema:CreateDatabase</code> 经各库的维护库建库。从库只在 PostgreSQL 上实测过，Oracle 能建表但还不能部署（见<a href="./backend/database#支持的数据库">数据库配置</a>）</li><li><strong>新增</strong> 在线聊天的语音与视频通话：单聊里一对一，群聊与部门群里点名邀请、没被邀请的成员可以中途加入（人数上限在系统参数 <code>chat.policy</code>，语音缺省 8 人、视频 6 人），通话中可共享屏幕、静音、关摄像头、换设备，任何页面都能接听，离开聊天页通话不断，来电与等对方接听时连着响铃，一直响到接通、挂断或响铃到点，结束后会话里留一条通话记录。媒体在浏览器之间直连（WebRTC），服务端只记通话状态、经聊天 Hub 转发信令；直连不通的网络要在宿主 <code>BasicApp:Chat:Calls</code> 配 STUN / TURN，TURN 用后端签发的限时凭据（见<a href="./backend/chat#语音与视频通话">在线聊天</a>）</li><li><strong>新增</strong> 屏幕共享可以单独发起：会话头多一颗「屏幕共享」钮，先挑要共享的画面再呼叫（群里先点名），对方按语音接听、进来就看到屏幕；它是通话的第三种媒体 <code>Screen</code>，人数上限与视频通话相同，通话记录与会话预览写「[屏幕共享]」</li><li><strong>新增</strong> 聊天显示在线状态：单聊头部、会话列表、成员与选人列表标出谁在线，上下线实时推送；刷新页面与断线重连有一段宽限（<code>BasicApp:Realtime:Presence:OfflineGrace</code>，缺省 8 秒），别人看到的不闪</li><li><strong>新增</strong> 聊天的多选转发：消息右键进多选，逐条转发或合并成一条聊天记录（卡片，点开按原来的先后看里面的消息，可以套着再转）；群主与管理员可以提及所有人</li><li><strong>新增</strong> 聊天的跨会话搜索（会话列表的搜索框同时找聊天记录，点命中定位到那条消息）、会话的图片与文件汇总、成员资料卡（部门、在线、共同的群，可直接发消息或通话）</li><li><strong>新增</strong> 桌面通知（缺省打开，偏好设置里可关）：只在页面看不到（窗口最小化、切到别的标签页或被别的窗口整个挡住）时发，页面看得到时即使窗口没有焦点也不发；提醒聊天消息、站内通知与来电（来电那条挂着不消失，有了结果即收起），点了回到对应的会话，同一个会话的后一条照样弹出；浏览器的授权在进入页面后的第一下操作时询问一次。页面标题上显示未读数；聊天的文件可以拖进消息流发送，视频附件在气泡里就地播放</li><li><strong>新增</strong> 聊天会话的右键菜单加「隐藏会话」：只从自己的列表里拿掉，置顶、免打扰与未读都不动，未读不计入角标；来了新消息自己回到列表，按名字搜得到，再打开也回到列表（<code>chat-conversations.hide</code>，会话列表项多了 <code>isHidden</code>）</li><li><strong>新增</strong> 群主可以解散群：全部成员移出，谁的会话列表里都不再有它；消息留着，聊天审计照样查得到，带解散时间与解散时的成员</li><li><strong>新增</strong> 聊天审计加「通话记录」页签：列出当前一侧全部会话的通话——谁发起、谁参与、各自的状态、结果与时长，不含通话内容</li><li><strong>新增</strong> 聊天里回复的引用块可以点，定位到被回复的那条消息；正文里被 @ 的人可以点，打开他的资料卡</li><li><strong>新增</strong> 站点设置与租户品牌：新页面「站点设置」（平台管理 › 系统设置）可以改系统名、Logo、浏览器图标、登录页的标语与说明，以及页脚的版权方与备案号，侧栏、浏览器标题、登录页、水印与页脚都从这里取值。租户在自己一侧改品牌，只填要改的项，没填的以灰字显示并沿用平台的值（新库的套餐里基础版及以上才能改）。设置存在系统参数 <code>settings.site</code>（缺省系统名 <code>XiHan.BasicApp</code>、版权方 <code>XiHanFun</code>），写错的值保存时即拒绝（<code>SETTINGS_VALIDATION_011</code>）；Logo 与浏览器图标上传前先按正方形裁剪，认 PNG、JPEG、WebP 与 ICO，不超过 2 MB。平台可以给租户绑自定义域名（<code>tenants.create</code> / <code>update</code> 的 <code>domain</code>，一个域名只能绑一个租户，否则 <code>TENANCY_CONFLICT_018</code>），没登录时按访问的域名显示该租户的品牌并预填租户框；停用或到期的租户不按域名显示，身份仍只认令牌。相关操作 <code>site.get</code> / <code>site.update</code>（<code>settings.site.read</code> / <code>update</code>）与匿名的 <code>site.resolve</code>；前端的 <code>VITE_APP_TITLE</code> 等四个品牌变量和偏好里的版权、备案项随之去掉（见<a href="./backend/settings#站点设置与租户品牌">参数与字典</a>）</li><li><strong>新增</strong> 密码策略收进系统参数 <code>identity.password</code>，参数配置页改了立即生效：最短长度 <code>minLength</code>（缺省 8，6 到 128）；须含字母、数字（缺省都要）与大写、小写、其他字符（缺省都不要）；不得与最近 <code>historyDepth</code> 个用过的密码相同（缺省 3，0 不检查）；有效天数 <code>expiryDays</code>（缺省 0 不过期，最多 3650）。设密码的各个入口按同一份规则校验，提示第一条不满足的规则；注册、找回与改密的表单按 <code>auth.login-config</code> 新带的 <code>passwordPolicy</code> 提前提示。密码过期的账号凭密码登录时，会话锁定到改密为止，并收到「密码已过期」站内信；写错的值保存时即拒绝（<code>SETTINGS_VALIDATION_011</code>）。宿主配置 <code>BasicApp:Auth:PasswordMinLength</code> 与 <code>PasswordHistoryDepth</code> 去掉（见<a href="./backend/authentication#密码策略">认证</a>）</li><li><strong>新增</strong> 账号安全站内信：登录时（五种登录方式都算）账号在别的设备上还登录着，就给那些设备发「账号在其他设备登录」或「账号在新设备登录」，带新登录的浏览器、系统、IP 与地点；别处都没登录着时给这次登录发「登录成功」。退出登录、被管理员强制下线、改密码、改用户名、绑定第三方账号，以及新建、滚动、删除 API 凭证，也各发一条。站内信只进本人的收件箱，不看通知偏好，投递失败不挡业务；「新设备」按登录请求新带的 <code>deviceId</code>（前端报浏览器指纹）判断，会话记下这个标识，指纹只决定措辞，不作安全判定（见<a href="./backend/authentication#安全通知">认证</a>）</li><li><strong>新增</strong> 角色页的权限分「授予」「拒绝」「有效期」三个页签。可以拒绝权限：只在这个角色与继承它的下级角色里生效，同一用户经别的角色或直接授权拿到的同一权限不受影响。新授予、新拒绝的权限可带生效时间、到期时间与原因；成员页签加成员时也可设有效期；已有的授予、拒绝与成员在「有效期」页签里逐条改（<code>roles.grant</code> / <code>deny</code> / <code>update-member</code>，见<a href="./backend/permission#角色">权限管理</a>）</li><li><strong>新增</strong> OAuth 服务端的签名密钥可以轮换与停用：「应用管理」页的「签名密钥」抽屉列出每把密钥与状态（签名中、待接替、仅验证、已停用），不显示私钥。轮换出的新密钥即刻在 JWKS 公布，15 分钟后接替签名，已有一把待接替时不能再轮换；停用后 JWKS 不再公布这把密钥，它签过的 id_token 也随之验不过，正在签名的不能停用，停用待接替的即取消这次轮换。权限码 <code>openplatform.oauth-signing-keys.read</code> / <code>rotate</code> / <code>retire</code>，只在平台一侧（见<a href="./backend/open-api#签名密钥">开放平台</a>）</li><li><strong>新增</strong> 菜单可以建内嵌节点（<code>menus.create</code> 的 <code>kind</code> 为 <code>Embed</code>）：外部地址在应用里的 iframe 中打开，路由按编码生成为 <code>/embed/&lt;名&gt;</code>，能进标签栏、能固定，新建时即可设固定标签；侧栏与顶部菜单在内嵌项后显示窗口图标，与外链的图标区分。帮助中心的「官方文档」改为内嵌打开本项目的文档站；对方站点禁止被嵌入时浏览器不显示（见<a href="./backend/permission#菜单">权限管理</a>）</li><li><strong>新增</strong> 页面登记与内置目录可以带缺省徽标：「AI 中心」目录带品牌色的「new」，「项目概览」带成功色的圆点；没被定制的页面随种子对齐，<code>menus.reset</code> 恢复到登记的徽标，不再清空。菜单编辑里「标签类型」下拉的每一项用对应的颜色示意</li><li><strong>新增</strong> 版本管理（平台管理 › 系统服务）显示每个库的库类型、结构状态（最新、待升级、升级中、升级失败、不可达）、应用的结构版本与最近一次失败的原因，并加三个动作：「预览升级」只读列出这个库要执行的脚本（带原文）和要建的表、列与索引（<code>versions.plan</code>，与 <code>schema plan</code> 同一份）；「重试升级」重新升级一个租户独立库，只锁这个库（<code>versions.upgrade</code>，权限 <code>maintenance.versions.upgrade</code>）；「释放升级锁」在持锁节点已退出时手动放锁（<code>versions.release-lock</code>，权限 <code>maintenance.versions.release-lock</code>）。升级记录可以按库筛选，同一次升级的步骤共用一个批次号，单条带执行的 SQL（见<a href="./backend/upgrade#版本与升级记录">表结构升级</a>）</li><li><strong>新增</strong> 声明了导出的列表页都接上导出中心（只有部门树仍是本地 CSV）：除用户与六种日志页外，角色、权限、菜单、委托与授权申请、字段安全、约束规则、租户、套餐、岗位、在线用户、权限变更与条件命中日志、文件、OAuth 应用、消息模板、邮件与短信记录、通知公告、参数、字典与字典项、业务编号、定时任务与版本也能在后台导出 CSV 或 Excel；权限目录、菜单、套餐这类一次返回整份的列表只给「全部」一档，菜单整棵树按先序展开成行；导出中心的业务类型显示成导出它的页面或页签的标题。<code>export-tasks.submit</code> 的列 <code>key</code> 改为取值路径（点号接下一层、数组用下标，<code>|</code> 分隔几条备选），原来只写属性名的照常可用（见<a href="./backend/file#导出中心">文件</a>、<a href="./frontend/schema-page#导出与导入">列表页</a>）</li><li><strong>新增</strong> 列表页的条件预设：从搜索区的书签按钮打开。「当前条件」逐条列出现在的筛选（字段名与选项名、日期区间、多选的值）、排序与每页条数，填个名称点右上角保存（名称框里回车也行）就存成预设，同名覆盖。「预设条件」里点名称即套用，悬停可看它存的条件，点眼睛先预览、再点一次还原；星标设为默认后，打开页面直接按它查询，不会先按空条件查一遍。跨设备同步由偏好设置「通用 → 同步」里单独的「条件预设」开关控制，缺省开（见<a href="./frontend/schema-page#个人设置">列表页</a>）</li><li><strong>新增</strong> 偏好设置「外观 → 其它」加「高对比度模式」：描边、输入框边框、分隔线与图表网格换成更深的实色，半透明的面板改为实底并去掉阴影与模糊，下拉、菜单等浮层同一档；随偏好跨设备同步（见<a href="./frontend/theme#偏好与同步">布局与主题</a>）</li><li><strong>新增</strong> 新版欢迎页：登录后首次进入新的版本线时出现一次，各国问候与应用标志由沙粒聚成又吹散，接着一屏屏介绍这一版的变化（界面、命令面板、灵动岛、聊天、通行密钥、工作台），没开的模块、没有权限的页面对应的那一屏不出现；看过记在账号上，换设备不再出现，「关于」页的「新版亮点」可以重看；构建时 <code>VITE_APP_WELCOME=false</code> 关闭。各能力包可以登记自己的亮点（见<a href="./frontend/welcome">新版欢迎页</a>）</li><li><strong>新增</strong> 文件库上传先试秒传（200 MiB 以内，内容相同的文件不再重传）；分片上传的单片失败会换新地址重试，断网、刷新或关页中断后，再传同一个文件只补没传完的分片（见<a href="./backend/file">文件</a>）</li><li><strong>新增</strong> 文件可以复制到另一条存储配置（<code>files.copy-storage</code>，用修改文件的权限）：从主副本读出、按 SHA-256 核对后写成正常、已校验的非主副本，再设为主副本即把文件迁过去；文件库「存储副本」抽屉加「复制到其他存储」</li><li><strong>新增</strong> 知识库文档可以看详情（索引状态、失败原因与原文）；检索试玩关掉「生成答案」时只检索，命中片段的标题点开即看所属文档，原文里标出这一段</li><li><strong>新增</strong> 配置的 JSON Schema（宿主工程的 <code>ConfigurationSchema.json</code>）：描述 <code>XiHan</code> 与 <code>BasicApp</code> 两节每个键的类型、枚举、取值范围、缺省值与说明，Visual Studio 打开 <code>appsettings*.json</code> 即有补全、悬停说明与校验，VS Code 与 Rider 的映射见<a href="./configuration#json-schema">配置参考</a></li><li><strong>新增</strong> 前端 <code>.env.development</code> 与 <code>.env.production</code>；后端正式环境的值写在不入库的 <code>appsettings.Production.json</code></li><li><strong>新增</strong> 灵动岛开放分区：调用方可指定胶囊与展开视图首行两侧的小件（图标、头像、进度环、短文本、计时、自定义组件）、正文下方的内容块（文本、大号数值、线形进度、列表、网格、图片、自定义组件）、底部图标栏，以及是否自动展开、停留时长与能否移除（见<a href="./frontend/dynamic-island">灵动岛</a>）；卡片与面板的内容铺满整宽，聊天消息上岛时标题前显示发送人头像</li><li><strong>新增</strong> 消息记录与工作流事件回执的保留清理：作业 <code>notification.messages.cleanup</code> 每天按平台参数 <code>notification.retention-days</code>（缺省 180 天）删除已结束的邮件、短信与机器人消息发送记录、Telegram 出站审计，以及系统自动发的站内通知（流程待办、账号安全提醒等）连同收件箱条目，排队中与发送中的不动，管理员发的通知公告不删；作业 <code>workflow.receipts.cleanup</code> 删除 90 天前的工作流事件回执（见<a href="./backend/scheduling#内建作业">定时任务</a>）</li><li><strong>新增</strong> 内建字典：业务按编码依赖某本字典的包经 <code>AddDictCatalog</code> 登记，种子 <code>settings.dicts</code> 写成平台的内建字典，名称、分类、说明与登记的项随版本对齐，状态、排序与另加的项归运营；内建字典与登记的项不能删（见<a href="./backend/settings#内建字典">参数与字典</a>）</li><li><strong>新增</strong> 代码生成的内置模板记下正文出自哪个嵌入文件：种子写入资源路径（<code>Templates/…</code>），模板详情返回 <code>templatePath</code>，自定义模板为空</li></ul><h3 id="调整" tabindex="-1">调整 <a class="header-anchor" href="#调整" aria-label="Permalink to “调整”">​</a></h3><ul><li><strong>调整</strong> 表结构改由 ORM 按实体建出，各种库、开发与正式环境走同一条路径：新库按实体建出全部表并登记当前结构版本；已有库先执行比台账新的、本库类型的升级脚本，再按实体补缺的表与列（升级记录里记一步 <code>orm-sync</code>），只在新库、执行了脚本或应用版本变了时做。基线 <code>Schema/6.0.0/0001-baseline.sql</code> 去掉；升级脚本只放 ORM 做不了的改动（改名、改类型、删列、搬数据），按库类型分目录 <code>Schema/&lt;版本&gt;/&lt;库类型&gt;/*.sql</code>，租户独立库的在其下的 <code>tenant/</code>，没有脚本时 <code>Schema</code> 目录可以不存在。建表一律只增不改，开发环境的 <code>InitTables</code> 也不再删掉实体里没有的列，不再按实体改已有列的类型、长度与可空（见<a href="./backend/upgrade">表结构升级</a>）</li><li><strong>调整</strong> 结构版本升到 <code>6.0.1</code>，新库直接登记为 <code>6.0.1</code>。PostgreSQL 的已有库启动时执行 <code>Schema/6.0.1/postgresql/0001-passkey-credential-hash.sql</code>：给通行密钥加凭据 ID 的 SHA-256 列 <code>credential_hash</code> 并回填，唯一索引由 <code>ux_sys_user_passkey_credential_id</code> 换成 <code>ux_sys_user_passkey_credential_hash</code>（凭据 ID 最长 1364 个字符，超过 MySQL 与 SQL Server 的索引键上限）</li><li><strong>调整</strong> 租户独立库升级失败不再中断启动：平台库失败照旧中断；独立库失败时接着升下一个库，这个租户在升级成功之前的调用一律 503（<code>RUNTIME_UNAVAILABLE_007</code>），健康项 <code>basicapp.schema</code> 降级，别的租户与平台照常。节点进入服务状态后把已就绪的独立库核对一遍，之后每分钟复查不可用的库，别的节点或版本管理页重试成功后随之放行。只有独立库失败时，<code>schema upgrade</code> 照样输出报告（<code>from</code>、<code>to</code>、<code>applied</code>、<code>runId</code>、<code>failures</code>）再以失败退出。新命令 <code>schema plan</code> 不启动应用、只读输出每个库要做的变更，发版前可以用新版本的程序对旧库跑一遍（见<a href="./backend/upgrade#执行时机">表结构升级</a>）</li><li><strong>调整</strong> 核心包的操作定为稳定（Stable）：Identity、Tenancy、Organization、Access、Settings、Notification、Files、Auditing、Maintenance、OpenPlatform 的操作，连同这些包与 Runtime、Realtime 的清单，6.x 内不改操作 ID、路由、请求与响应字段、权限码与错误码，要去掉的先标 <code>Deprecated</code>、下个大版本再删。可选模块 Chat、Workflow、CodeGeneration、AI、Printing、Workbench 与代码生成出的操作仍是预览（Preview），小版本里可能破坏；<code>openapi.json</code> 只给非 Stable 的操作写 <code>x-xihan-stability</code>（见<a href="./backend/development#三、实现操作">开发流程</a>）</li><li><strong>调整</strong> 实体的表名、列名、长度、可空、说明与索引名都显式写在实体上，不再由类名、属性名按命名约定推出（缩写会被拆错）；拆错的名字随之改正：表 <code>sys_o_auth_app</code>、<code>sys_o_auth_code</code>、<code>sys_o_auth_consent</code>、<code>sys_o_auth_signing_key</code>、<code>sys_o_auth_token</code> 改为 <code>sys_oauth_app</code>、<code>sys_oauth_code</code>、<code>sys_oauth_consent</code>、<code>sys_oauth_signing_key</code>、<code>sys_oauth_token</code>（主键约束与索引名随之改为 <code>sys_oauth_*</code>），<code>sys_code_gen_table_column</code> 的列 <code>c_sharp_type</code>、<code>c_sharp_property</code> 改为 <code>csharp_type</code>、<code>csharp_property</code>，其余表名、列名与索引名不变。代码生成出的实体同样显式写表名、列名、长度、可空、说明与唯一索引名（见<a href="./backend/entity">实体</a>）</li><li><strong>调整</strong> 账号的安全戳接上会话核对：会话签发时记下账号的安全戳，门禁与刷新令牌时对不上即失效，与改密并发的登录开出的会话也用不了；本人开关双因素时其余会话下线、当前会话照常可用，管理员重置双因素时该用户的会话全部下线（见<a href="./backend/authentication#令牌与会话">认证</a>）</li><li><strong>调整</strong> 标签栏的固定标签改由菜单决定：菜单里设为固定标签的页面在菜单装好后就排在最前（没访问过也在，直接打开别的页面时也带着它的标题与图标），不能关闭，也不能取消固定。工作台登记为缺省固定，首页不再特殊，不固定时可以关；手动固定的标签照旧可以取消（见<a href="./frontend/routing#标签页与缓存">菜单与路由</a>）</li><li><strong>调整</strong> 顶层目录「系统管理」改称「平台管理」，其下新增「打印服务」目录，打印模板从「在线开发」移到这里；日志页「条件命中」改称「条件命中日志」</li><li><strong>调整</strong> 系统投递的站内信（流程待办、账号安全提醒）只留在本人的收件箱里：通知公告管理的列表不再列出，按 ID 的查看、统计、提醒与删除都当作不存在；工作台的公告小组件也不再列出它们（见<a href="./backend/messaging#站内通知">消息通知</a>）</li><li><strong>调整</strong> 邮件、短信与机器人消息模板的变量 <code>brand</code> 在调用方没传时，取发送这一侧站点设置的系统名，租户发出的消息带它自己的品牌；配置项 <code>BasicApp:Notification:Brand</code> 去掉（见<a href="./backend/messaging#消息模板">消息通知</a>）</li><li><strong>调整</strong> 聊天的保留清理也删结束早于保留期的通话与参与记录，以及只挂在过期消息上的附件文件；留存的消息（含转发与聊天记录）还在用的文件与会话头像不删（见<a href="./backend/chat#策略与保留清理">在线聊天</a>）</li><li><strong>调整</strong> 去掉用户统计表 <code>sys_user_statistics</code>：计数从不更新、也没有读取方，最近登录看用户的最后登录时间，登录次数看登录日志；去掉聊天的两个用不上的索引（会话的最后消息时间、表情回应的会话），会话的最后消息时间随每条消息更新，少维护一个索引</li><li><strong>调整</strong> 顶栏的上下文切换钮（显示当前平台或租户，点开进控制中心切换）改为品牌色虚线描边钮，和左边那排工具钮之间隔一道分割线，去掉下拉箭头；平台一侧显示「平台管理」（与控制中心切换页的标题一致），不再显示「平台」</li><li><strong>调整</strong> 语言菜单里各语言一律写它自己的名字（简体中文、正體中文、English、日本語……），不随界面语言翻译</li><li><strong>调整</strong> 偏好设置「布局」里单独的「版权」一节并入「底栏」，开关改叫「显示版权信息」，关掉底栏时置灰；存储键随之更换，之前存下的开关不再读取</li><li><strong>调整</strong> 对话框与抽屉的宽度改按容器档取，随偏好设置里的「字号」等比缩放。缺省字号下多数只差几十像素（编辑弹窗缺省由 640px 变为 672px），代码生成的列配置（原 1280px）以及通知公告、代码模板的大编辑框（原至多 1400px）都收到 1120px</li><li><strong>调整</strong> 灵动岛去掉「最近」历史，面板只列当前的活动；胶囊不再有下拉箭头、面板不再有标题与收起钮，鼠标停在岛上即展开详情、移开收起（触屏点按、键盘 Enter 照旧）</li><li><strong>调整</strong> 免打扰的会话不再响提示音、不上灵动岛，也不发桌面通知；未读照记</li></ul><h3 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to “优化”">​</a></h3><ul><li><strong>优化</strong> 参数、字典选项、用户设置、部门树（含各部门成员数）与发送时取的消息模板加了读穿缓存，写入在提交后即失效；配了 Redis 时各实例共享（见<a href="./backend/caching#缓存时长与失效">缓存与异步</a>）</li><li><strong>优化</strong> 权限授予与租户目录的缓存改走框架缓存：授予、撤销、停用租户、改独立库连接与删除租户在提交后即失效，配了 Redis 时各实例一起失效，不用再等别的实例的缓存过期（原先最多 30 秒）；分库解析每次读租户目录，不另缓存。缓存容量由 <code>XiHan:Caching</code> 的本机缓存管（<code>InMemory:MaxEntries</code> / <code>Hybrid:LocalCapacity</code>），原来的容量与分片缓存配置删除。新增 <code>XiHan:Localization:Database:ChangeCheckIntervalSeconds</code>（缺省 1 秒），别的实例写入的数据库译文最迟这么久后重新加载（见<a href="./backend/caching#缓存时长与失效">缓存与异步</a>）</li><li><strong>优化</strong> 业务表单（含代码生成的页面）里的文件与图片字段 <code>XFileRefUpload</code> 与文件库走同一条上传路径：先试秒传、大文件分片，上传时显示进度，中断了留下提示与「继续上传」钮，分片上传的只补没传完的分片；文件不再在前端限 10MB，以 <code>BasicApp:Files:MaxUploadBytes</code>（缺省 100 MiB）为准，图片仍缺省 10MB；拒收时按类型不支持、超过大小、一次选了多个分别提示，不再一律说超过大小（见<a href="./backend/file#上传与下载">文件</a>）</li><li><strong>优化</strong> 换了主题色后壳层的字更看得清：侧栏与顶部菜单的文字改用正文色；未选中的标签、面包屑可点的层级、命令面板入口与键帽、顶栏下拉箭头取正文色的 85%，原来是次要色。顶栏一排图标钮一样大（主题、全屏、通知、聊天原来不齐），悬停、按下与开着面板时铺品牌浅底；没有头像图片时，头像里放不下两个汉字就只放一个</li><li><strong>优化</strong> 顶栏通知与聊天钮的未读角标换数时逐位滚动（变大往上、变小往下），减弱动效下直接换字</li><li><strong>优化</strong> 模仿登录的提示改为常驻在灵动岛上，展开即可退出模仿；偏好里关掉灵动岛时仍显示顶部横幅。灵动岛胶囊上的常驻状态（模仿登录、网络或实时连接断开）不再给图标画圆底</li><li><strong>优化</strong> <code>appsettings.json</code> 与 <code>appsettings.Development.json</code> 不再逐项注释，说明改由 JSON Schema 与配置参考提供；框架节的列表与字典写成空的 <code>[]</code> / <code>{}</code> 时编辑器直接报错；配置参考补上配置节点总览</li><li><strong>优化</strong> 收到聊天消息与站内通知的提示音拉开，一听就分得出来</li><li><strong>优化</strong> 聊天的选人改成可勾选的列表（可搜索、只看最近联系人或按部门筛选、逐页加载）；群信息、公告、成员治理与个人设置收进会话详情侧栏</li><li><strong>优化</strong> 定位到消息（引用块、搜索命中、置顶）时整行铺一条底色，不再只描气泡的边；提及列表的当前行铺底、跟着指针与键盘走</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to “修复”">​</a></h3><ul><li><strong>修复</strong> 前端调用没有超时：每次调用缺省带 60 秒的截止时间（<code>xihan-deadline</code>），后端到点取消并回 504 <code>KERNEL_TIMEOUT_001</code>；后端挂死或网络中断时，前端在截止时间过后 5 秒自己中止，提示「请求超时，请稍后重试」，不再一直等。调模型（知识库导入、重建索引、检索与问答、连通测试、助手回复）、生成代码、合并分片、跨存储复制与校验、重试升级独立库放宽到 5 分钟；自己的调用可以用 <code>CallOptions.timeoutMs</code> 改（<code>0</code> 不设截止时间，见<a href="./frontend/request#请求头">请求与契约层</a>）</li><li><strong>修复</strong> 软删除实体的并发写入越过操作里的检查、撞上唯一索引时，返回 409 <code>PERSISTENCE_CONFLICT_003</code>（<code>index</code> 是索引名）并回滚，不再是框架识别不了的数据库错误。软删除实体的唯一约束改用框架的 <code>[EntityIndex(…, IsUnique = true, Name = …)]</code>，代码生成出的实体随之换用（见<a href="./backend/data-model#索引与唯一性">数据模型</a>）</li><li><strong>修复</strong> 文件下载先只取第一个字节探一下签名地址：存储不可用、文件已删或地址失效时在当前页提示「文件暂时无法下载，可能已被删除或存储不可用」（本地存储按后端给的本地化原因），不再让浏览器跳到错误响应上；S3 兼容存储的桶要给前端的来源放行跨域 <code>GET</code>（见<a href="./backend/file#上传与下载">文件</a>）</li><li><strong>修复</strong> 列表页的页面设置（列设置、搜索设置、条件预设等）在账号上那份还没拉到或拉取失败时不再上传：原来只带改动那一项的载荷，会把同一页存在账号上的其他设置抹掉。拉不到时灵动岛提示同步失败，改动留在本机等下一次保存；退出登录或切换身份后，上一个人还没传上去的页面设置也不会写进新身份</li><li><strong>修复</strong> 列表页连着翻页、搜索或排序时只认最后一次请求：先发的请求后回来不再盖掉结果，加载状态与失败提示也只看最后一次</li><li><strong>修复</strong> 列表页搜索区「重置」清空筛选后回到列设置里的默认排序，不再变成不排序；换了设备首次打开也按账号上的默认排序查询</li><li><strong>修复</strong> 平台一侧给角色加成员、建委托、配字段安全与约束规则、试算权限条件与访问策略时，选人列表只列平台账号，不再混入租户的用户</li><li><strong>修复</strong> 非中文界面下仍显示中文的文案改按界面语言显示：聊天会话列表预览、回复引用与搜索命中里的图片、文件、语音标签，AI 模块没装时发起助手会话的提示，以及直接打印的各类错误提示；会话列表的预览与回复引用、搜索命中改用同一套标签，语音消息的预览由「[文件] 文件名」改为「[语音] N 秒」</li><li><strong>修复</strong> 色弱模式改用红绿色觉校正滤镜：明暗与对比度不变，只把红绿差异挪到蓝黄方向。原来的滤镜近乎把整页反色，页面会变暗</li><li><strong>修复</strong> 法语等长文本语言下，面包屑某一级顶到自身最大宽而截断，不再被当成顶栏挤不下，位置设为「自动」的顶栏工具不再一路让到悬浮组</li><li><strong>修复</strong> 被移出群（含随部门归属移出部门群）的人正开着那个群时，不再冒出「只有会话成员可以这样做」：会话直接从他的列表里拿掉，并提示他已被移出哪个群；推送 <code>ChatConversationChanged</code> 给出去的人另用 <code>removed</code>（被移出）与 <code>left</code>（自己退群）两种，留下的成员照旧是 <code>member-removed</code> / <code>department-kicked</code></li><li><strong>修复</strong> 分片上传完成时拼出的大小与声明的不符，上传记为失败（<code>Failed</code>）并留下错误码，不再一直显示上传中、续传与完成只拿到存储的错误直到过期</li><li><strong>修复</strong> Telegram 机器人名称的托管与 Webhook 路由改为区分大小写，与名称的唯一索引一致：<code>Ops</code> 与 <code>ops</code> 是两个机器人，不再只托管其中一个</li><li><strong>修复</strong> 宿主启动失败时（如启动核对不通过），日志里不再多出维护模式轮询的后台服务故障（Error 与 Critical）：这个轮询改在 Runtime 启动之后才开始，随它停止</li></ul><h2 id="v6-0-0-preview-2-2026-11-13" tabindex="-1">v6.0.0-preview.2 (2026-11-13) <a class="header-anchor" href="#v6-0-0-preview-2-2026-11-13" aria-label="Permalink to “v6.0.0-preview.2 (2026-11-13)”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，正式版前接口、配置与表结构仍可能调整。</li><li>后端依赖 XiHan.Framework 5.0.0-rc.1，前端依赖 XiHan.UI 5.5.2。</li><li><strong>按 preview.1 建的库要新建</strong>：6.0.0 基线的 <code>tenant_record</code> 加了 <code>is_deleted</code>、<code>deleted_at</code> 两列，台账里已是 6.0.0 的库不会再执行基线，启动读租户目录时即失败。开发环境删掉库直接启动即可（自动建库、建表、播种）。</li><li>系统参数 <code>identity.login-methods</code> 改为方式名的 JSON 数组（如 <code>[&quot;password&quot;,&quot;passkey&quot;]</code>），原来逗号分隔的写法不再认。</li><li>租户 ID 只收小写；不带租户的授予只对平台调用生效，平台账号切换进租户后不再带着平台的权限（超级管理员的 <code>*</code> 也一样）。</li></ul></div><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to “新增”">​</a></h3><ul><li><strong>新增</strong> 通行密钥（Passkey）登录：个人中心「安全设置」先核对密码再登记，登录页不填账号即可用指纹、面容或设备密码登录；宿主配了 <code>XiHan:Security:WebAuthn</code> 的依赖方 ID 与来源、系统参数 <code>identity.login-methods</code> 列出 <code>passkey</code> 才开放（见<a href="./backend/authentication">认证</a>）</li><li><strong>新增</strong> 内建参数：各包代码读取的系统参数（登录方式、密码策略、模仿登录、聊天策略、日志保留天数等）都由种子 <code>settings.configs</code> 建成平台的内建参数，名称、分组、类型、缺省值与说明随版本对齐，值归运营；内建参数不能删、不能改数据类型（见<a href="./backend/settings">参数与字典</a>）</li><li><strong>新增</strong> 用户批量导入（<code>users.import</code>，用新建用户的权限）：用户页导入 CSV，这批用户共用导入弹窗里的初始密码并标记为须改密；每行按新建用户的规则校验，可一并加入部门（租户侧，要有加入部门的权限）、指派角色（要有指派角色的权限，照常过约束规则），有问题的行列出原因、其余照常导入</li><li><strong>新增</strong> 约束规则的「需审批」接上审批：管理员给用户指派角色或直授权限触犯它时，替该用户发起授权申请（结果里提示「已转审批」），审批通过后按原内容生效并在权限变更日志里记下批准的申请；拒绝类照旧拦下；别的变更没有审批的载体，按拒绝处理；动态职责分离的规则不能选需审批。流程变量 <code>constraintRule</code> 带上规则编码，流程定义可以据此路由</li><li><strong>新增</strong> 列表页提交到导出中心时可选 Excel（XLSX）：导出菜单分 CSV 与 Excel 两组，各有查询结果、当前页、全部三档</li><li><strong>新增</strong> 用户的「所属部门」可直接设主部门（行操作「更多」菜单里的「设为主部门」，原主部门随之取消）；加入部门时已加入的部门不能再选（<a href="https://github.com/XiHanFun/XiHan.BasicApp/issues/55" target="_blank" rel="noreferrer">#55</a>）</li><li><strong>新增</strong> <code>BasicApp:Schema:CreateDatabase</code>：升级前平台库不存在时先建库，缺省关，开发环境打开，首次运行不用先手工建库</li><li><strong>新增</strong> <code>BasicApp:Seed:RunOnStartup</code>：应用启动后执行一遍种子，缺省关，开发环境打开，首次运行即可用 <code>superadmin</code> 登录</li></ul><h3 id="调整-1" tabindex="-1">调整 <a class="header-anchor" href="#调整-1" aria-label="Permalink to “调整”">​</a></h3><ul><li><strong>调整</strong> 后端升到 XiHan.Framework 5.0.0-rc.1，并以 NuGet 包引用（版本见 <code>backend/props/framework.props</code>），克隆本仓库即可构建；后端镜像不再克隆框架源码，构建时要能访问 nuget.org。连框架源码调试时打开 <code>backend/XiHanFun.Local.slnx</code>（见<a href="./dev-environment#框架引用">框架引用</a>）</li><li><strong>调整</strong> 系统参数 <code>identity.login-methods</code> 改为方式名的 JSON 数组（可写 <code>password</code>、<code>email</code>、<code>phone</code>、<code>passkey</code>），缺省 <code>[&quot;password&quot;]</code></li><li><strong>调整</strong> 租户 ID 只用小写字母、数字与 <code>._-</code>（<code>^[a-z0-9][a-z0-9._-]{0,63}$</code>），新建租户、登录、切换租户、成员与模仿登录里填大写的直接校验失败；删除的租户 ID 不能再新建（框架在租户目录里留下删除标记）</li><li><strong>调整</strong> 健康探针 <code>/health/startup</code>、<code>/health/ready</code>、<code>/health/live</code> 只给总状态，不再列出各 Feature 与健康项；详情看服务监控（<code>maintenance.server.read</code>）</li><li><strong>调整</strong> 操作请求体上限 4 MiB（<code>XiHan:Protocols:Http:MaxRequestBodyBytes</code>）；MCP 入口校验 <code>Origin</code>（浏览器里的客户端要配 <code>XiHan:Protocols:Mcp:AllowedOrigins</code>）、只收 <code>application/json</code>；CloudEvents 入站只收 <code>XiHan:Protocols:CloudEvents:Topics</code> 映射过的事件类型，请求体与 batch 条数有上限（见<a href="./configuration#xihan-protocols">配置参考</a>）</li><li><strong>调整</strong> 种子写入的套餐、参数、字典、菜单与访问策略预置模板等的名称与说明改用中文</li><li><strong>调整</strong> 开发配置的平台库名改为 <code>xihan_basicapp</code></li><li><strong>调整</strong> .NET 服务包升到 10.0.15，含 SignalR Redis 背板的安全修复</li></ul><h3 id="优化-1" tabindex="-1">优化 <a class="header-anchor" href="#优化-1" aria-label="Permalink to “优化”">​</a></h3><ul><li><strong>优化</strong> 提示里查得到的对象写名称而不是 ID：部门、岗位、字典与字典项、参数、编号规则、通知、消息模板、附件、角色与租户成员等；查不到的不再在文案里显示 ID（仍随错误的 <code>details</code> 返回）（<a href="https://github.com/XiHanFun/XiHan.BasicApp/issues/55" target="_blank" rel="noreferrer">#55</a>）</li></ul><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to “修复”">​</a></h3><ul><li><strong>修复</strong> 平台一侧的授予（含超级管理员的 <code>*</code>）在租户里也生效：平台账号切换进租户后只按该租户的角色与授予判定</li><li><strong>修复</strong> 平台一侧用户的直接授权列不出来，跨两次授予的权限互斥也判定不到：平台级授予在授予表里存空字符串，读取时按契约的 null 比对</li><li><strong>修复</strong> 只有授权申请权限的用户打开「发起申请」时角色与权限候选为空、提交不了：候选改由新操作 <code>permission-requests.candidates</code> 给出，持有提交或重新提交授权申请的权限其一即可</li><li><strong>修复</strong> 重置密码与新建用户的初始密码提示、审批流的缺省节点名与授权申请接口的说明与实际行为不符</li><li><strong>修复</strong> 开发模式（<code>pnpm dev</code>）下流程设计器打不开</li></ul><h2 id="v6-0-0-preview-1-2026-11-10" tabindex="-1">v6.0.0-preview.1 (2026-11-10) <a class="header-anchor" href="#v6-0-0-preview-1-2026-11-10" aria-label="Permalink to “v6.0.0-preview.1 (2026-11-10)”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">预览须知</p><ul><li>这是预览版，正式版前接口、配置与表结构仍可能调整。</li><li>后端依赖 XiHan.Framework 5.0.0-preview.2（同级检出了框架时按 <code>backend/props/framework.props</code> 锁定的提交以源码构建，代码与这个包相同），前端依赖 XiHan.UI 5.5.1。</li><li>新部署要新建库：启动宿主（或先执行 <code>schema upgrade</code>）建表并写版本台账，再执行一次 <code>seed</code>。</li><li><strong>首次执行 <code>seed</code> 必须配 <code>BasicApp:Seed:SuperAdminPassword</code></strong>，没有公开的缺省密码（<code>appsettings.Development.json</code> 里的值只用于开发）。</li><li>非 Development 环境必须提供 <code>XiHan:Security:Jwt:Secret</code> 与 <code>XiHan:ObjectStorage:SignedUrls:Secret</code>（UTF-8 至少 32 字节），缺失或太短启动即失败。</li></ul></div><h3 id="架构与协议" tabindex="-1">架构与协议 <a class="header-anchor" href="#架构与协议" aria-label="Permalink to “架构与协议”">​</a></h3><ul><li><strong>新增</strong> 能力包：每个业务能力是一个 <code>IFeature</code>，分四层、只能向下依赖，由架构测试守护；可选模块（工作台、工作流、打印、代码生成、聊天、AI）用 <code>BasicApp:Modules:&lt;名&gt;:Enabled</code> 开关，缺省都开</li><li><strong>新增</strong> 操作契约：每个公开方法是一个 <code>[Operation(&quot;&lt;资源&gt;.&lt;动词&gt;&quot;)]</code>，路由、OpenAPI、gRPC 方法与 MCP 工具从同一份登记推导；每个操作显式声明暴露面，超出 HTTP 的逐个登记且必须只读，只读查询走 GET</li><li><strong>新增</strong> 成功响应就是 DTO，失败是 RFC 9457 <code>application/problem+json</code>，字段级错误放 <code>errors</code>（见<a href="./api-guide">接口对接指南</a>）</li><li><strong>新增</strong> 前端的类型、操作客户端、权限码、枚举与推送方法由后端导出的 <code>openapi.json</code>、<code>realtime.json</code> 生成，CI 重新生成后比对</li><li><strong>新增</strong> 文案与代码分离：每个包 10 种区域的消息目录，错误只带键与参数，由宿主按 <code>Accept-Language</code> 翻译；平台库 <code>message_translation</code> 可以按区域覆盖</li><li><strong>新增</strong> 接口文档的标题、标签、分组与字段说明本地化，<code>/openapi/&lt;组&gt;.json</code> 按包分组</li><li><strong>新增</strong> MCP 端点 <code>/mcp</code>：用户、部门、岗位、部门成员、权限、字典、知识检索与我的待办等只读目录类操作发布为 MCP 工具（见 <a href="./ai/mcp">MCP Server</a>）</li><li><strong>新增</strong> 网络调用方的租户只来自令牌：HTTP、gRPC、MCP 入站丢掉调用方写的 <code>xihan.tenant</code>、<code>xihan.principal</code>，进租户走 <code>auth.switch-tenant</code></li></ul><h3 id="账号与认证" tabindex="-1">账号与认证 <a class="header-anchor" href="#账号与认证" aria-label="Permalink to “账号与认证”">​</a></h3><ul><li><strong>新增</strong> 登录：密码、邮箱 / 手机验证码、第三方登录（GitHub、Gitee、Google、QQ、微信、企业微信、飞书、钉钉）、双因素（认证器、邮件、短信）、图形验证码、登录节流、账号锁定、自助注册（缺省关）与找回密码</li><li><strong>新增</strong> 注册要先勾选同意隐私政策与服务条款；两份文书按 10 种界面语言放在前端 <code>packages/views/_core/authentication/legal/</code>，<strong>部署前按自己的主体、联系方式与条款改写</strong></li><li><strong>新增</strong> 令牌与会话：HS256 访问令牌加不透明刷新令牌，每次刷新轮换；会话门禁、锁屏、按人或按会话强制下线；切换租户换令牌、整页重建</li><li><strong>新增</strong> 每个账号可以限制同时登录：不允许多端或限定设备数</li><li><strong>新增</strong> 个人中心：资料、裁剪后上传头像（圆形取景、存正方形）、改用户名、改密、联系方式验证与换绑、双因素、第三方绑定、登录设备与日志、使用统计；可以停用或注销本人账号（要当前密码，模仿会话不能做，租户所有者要先转移所有权）</li><li><strong>新增</strong> 系统内置账号（初始超级管理员、租户开通时的管理员）不能被停用、删除、锁定或由管理员重置密码，本人也不能改用户名或关闭账号</li><li><strong>新增</strong> 强制改密（系统参数 <code>identity.password</code> 的 <code>forceChange</code>，缺省关）：打开后，密码由他人设置的账号凭密码登录要先改密</li><li><strong>新增</strong> 模仿登录：缺省 30 分钟并通知被模仿者（系统参数 <code>identity.impersonation</code>，最多 480 分钟），时长是硬期限，能刷新但不能续期；一条原会话同时只挂一条模仿会话；不能选超级管理员或同级、更高权限的账号；模仿态拒绝接管账号、变更授权、销毁数据、重置 OAuth 客户端密钥与处理授权申请</li><li><strong>新增</strong> 用户管理：真实姓名、性别、生日、国家与备注；列表带头像、地区、角色、部门与安全标记，详情看验证状态、双因素、今日统计与当前会话</li><li><strong>新增</strong> 密码哈希 PBKDF2-SHA256，迭代 60 万次</li></ul><h3 id="权限与访问控制" tabindex="-1">权限与访问控制 <a class="header-anchor" href="#权限与访问控制" aria-label="Permalink to “权限与访问控制”">​</a></h3><ul><li><strong>新增</strong> 授予来自框架 <code>Security.Database</code>；Deny、授予与指派的有效期、用户直授、角色继承、限时委托、套餐门控与 ABAC 条件逐层收窄</li><li><strong>新增</strong> 权限目录由代码登记、从操作登记派生，页面只读，权限名按界面语言显示；启停并入修改权限，角色的收回权限、移出成员、解除上级并入授予的那一个码</li><li><strong>新增</strong> 数据范围（角色与用户级）在查询里显式套用；字段安全按实体、字段与角色 / 用户 / 部门配置六种读取方式，在投影时套用</li><li><strong>新增</strong> 访问策略：平台与租户两层、三个时机、六个模板，能试运行并记命中，有防自锁；只管外部协议（HTTP、gRPC、MCP），不管作业、消息处理与工作流；登录失败自动封禁</li><li><strong>新增</strong> 约束规则五类（SSD、DSD、权限互斥、基数、条件）与会话角色激活</li><li><strong>新增</strong> 授权申请：为自己申请角色或权限，提交即发起审批，通过即自动授予；工作流关掉时照常列出、不能提交</li><li><strong>新增</strong> 作用侧在运行时判：租户主体持 <code>*</code> 也调不到只属于平台的操作，反过来同样</li><li><strong>新增</strong> 代他人委托时，操作者自己也要持有所委托的权限或角色；改别人的邮箱或手机号要有重置密码的权限，系统账号的联系方式只有本人能改，也不能被重置双因素</li><li><strong>新增</strong> 菜单：页面节点由各包登记生成、只调展示，没有按钮节点；运营可另建目录与外链</li></ul><h3 id="组织与租户" tabindex="-1">组织与租户 <a class="header-anchor" href="#组织与租户" aria-label="Permalink to “组织与租户”">​</a></h3><ul><li><strong>新增</strong> 部门（闭包表）、岗位、部门成员；部门支持关键字搜索，带类型与联系方式，归属带备注</li><li><strong>新增</strong> 租户开通三步（创建、可选初始化独立库、初始化管理员）、停用恢复、换套餐、配额、到期生效、所有权转移、运维支持成员</li><li><strong>新增</strong> 租户的用户列表带出在别处注册、生效中的本租户成员（外部成员），能配本租户的角色、部门、数据范围与直授，账号本身只有注册地与平台能动；运维支持成员只读、能配角色，最近登录时间与 IP 不下发给租户，不占席位，不进模仿候选、群发收件人和聊天目录</li><li><strong>新增</strong> 套餐：价格、计费周期、配额、权限白名单、启停；停用的套餐不能再分配，已绑定的不受影响，缺省套餐必须启用</li><li><strong>新增</strong> 平台数据不实现 <code>IMultiTenant</code>，平台与租户两侧严格分开；租户库实体可随租户分库</li></ul><h3 id="消息与协作" tabindex="-1">消息与协作 <a class="header-anchor" href="#消息与协作" aria-label="Permalink to “消息与协作”">​</a></h3><ul><li><strong>新增</strong> 通知公告：定向投递、横幅与弹窗、强制阅读、提醒、阅读统计；正文用 Markdown 编辑器，HTML 渲染前净化</li><li><strong>新增</strong> 收件箱、消息模板（邮件、短信、站内通知、机器人，Scriban 变量，租户覆盖平台模板）、邮件短信发送记录、多通道配置、群机器人（钉钉、飞书、企业微信）、Telegram 机器人</li><li><strong>新增</strong> 在线聊天：单聊、群聊、部门群（随部门归属自动进出）、助手会话；撤回、编辑、表情回应、置顶、提及、已读回执、正在输入；转发由服务端一次完成，附件以会话为访问范围；聊天审计、敏感词与保留清理（系统参数 <code>chat.policy</code>）</li><li><strong>新增</strong> 实时推送：通知 Hub 与聊天 Hub；配了 Redis 时跨实例，配了 RabbitMQ 时强制下线还由所在实例断开；导出任务与通知发布的进度推到灵动岛</li><li><strong>新增</strong> 群机器人的 Webhook 地址加密存放，响应只给主机；解不开时不当明文用，发送失败并在发送记录里写明原因</li><li><strong>新增</strong> 验证码的发送记录不留正文、不能重发；发送记录、导出任务与助手回复的失败原因只记异常类型，完整异常看应用日志；机器人返回错误时只记状态码</li></ul><h3 id="文件与导出" tabindex="-1">文件与导出 <a class="header-anchor" href="#文件与导出" aria-label="Permalink to “文件与导出”">​</a></h3><ul><li><strong>新增</strong> 上传、秒传、分片上传、签名下载与预览（支持 Range）、元数据、归档、副本与主存储、校验</li><li><strong>新增</strong> 存储配置支持本地与 S3 兼容服务；不认 <code>If-None-Match</code> 的服务可以按条关掉条件写入</li><li><strong>新增</strong> 导出中心以发起人的身份逐页调列表操作，CSV / XLSX 存 7 天，到期的临时文件由作业 <code>files.temporary.purge</code> 清理；CSV 导出防公式注入</li><li><strong>新增</strong> 响应一律带 <code>X-Content-Type-Options: nosniff</code>；文件只有图片（不含 SVG）、音视频、PDF 与纯文本能内联打开，别的类型以附件下载；<code>/blobs</code> 除 PDF 外放进沙箱</li></ul><h3 id="日志与审计" tabindex="-1">日志与审计 <a class="header-anchor" href="#日志与审计" aria-label="Permalink to “日志与审计”">​</a></h3><ul><li><strong>新增</strong> 八类日志与按 trace-id 聚合的链路追踪；分表日志经有界队列批量写入，保留清理作业</li><li><strong>新增</strong> 操作日志的描述取操作的本地化标题；数据变更日志区分「恢复」，遮加密参数的值、AI 密钥、连接串与 Webhook 地址</li><li><strong>新增</strong> 访问日志与开放接口日志可以按耗时上下限筛选，异常日志可以按发生位置筛选</li></ul><h3 id="系统管理" tabindex="-1">系统管理 <a class="header-anchor" href="#系统管理" aria-label="Permalink to “系统管理”">​</a></h3><ul><li><strong>新增</strong> 参数（平台加租户覆盖、加密值不回显，关掉加密且不给新值时清空）、字典（树形项）、业务编号、用户设置（跨端同步）</li><li><strong>新增</strong> 任务调度：代码登记与运行时作业、Cron 构建器与固定间隔、暂停恢复、立即执行、改计划与恢复、失败重试与单次执行时限、运行历史</li><li><strong>新增</strong> 缓存管理按命名空间列键、查看、修改、删除；服务监控；版本台账与升级记录</li><li><strong>新增</strong> 表结构升级器：<code>Schema/&lt;版本&gt;/</code> 脚本加台账，平台库之后逐个升级已就绪的独立库，升级期间别的节点进入维护模式（503）</li><li><strong>新增</strong> 开放平台：签名开放接口与自助凭证、OAuth 2.0 / OIDC 服务端、OAuth 应用、我的应用、授权同意；CloudEvents 入站端点（缺省关，要 <code>runtime.cloud-events.deliver</code>，这个权限只在平台一侧）</li></ul><h3 id="工作流与审批" tabindex="-1">工作流与审批 <a class="header-anchor" href="#工作流与审批" aria-label="Permalink to “工作流与审批”">​</a></h3><ul><li><strong>新增</strong> 框架的数据库工作流，流程数据按平台与租户分区落表，随业务事务提交或回滚；全屏设计器、发布、版本、挂起恢复、取消终止、重试</li><li><strong>新增</strong> 受理人可按指定用户、发起人、表达式、角色、部门、部门负责人、岗位、发起人第 N 级主管与主管链配置</li><li><strong>新增</strong> 审批中心：待我审批、我已审批、我发起的、抄送我的；办理、转办、加签、撤回、审批轨迹；业务包可经审批业务接入</li><li><strong>新增</strong> 流程故障的原因按看的人的语言显示；活动抛异常或 <code>Http</code> 活动连不上时，原因只有异常类型，完整异常看应用日志</li></ul><h3 id="代码生成与打印" tabindex="-1">代码生成与打印 <a class="header-anchor" href="#代码生成与打印" aria-label="Permalink to “代码生成与打印”">​</a></h3><ul><li><strong>新增</strong> 代码生成：数据源、表结构导入、表与列配置、模板维护与预览（Scriban）、生成与生成历史、零代码只读运行时；单表、树表、主从三种模式生成的新包能编译、能过前端门禁，前端取数走生成的契约；产物包从生成历史下载；数据源换数据库类型时，端口跟着换成该库的缺省端口</li><li><strong>新增</strong> 生成到项目只在开发环境且打开 <code>BasicApp:CodeGeneration:EnableGenerateToProject</code> 时可用；表名不能改；零代码运行时不读应用自己的表；外部数据源过出站地址策略；SQLite 数据源缺省关（<code>BasicApp:CodeGeneration:AllowSqliteDataSource</code>）</li><li><strong>新增</strong> 打印模板：平台全局与租户模板、按编码解析、数据源经 <code>AddPrintDataSource</code> 登记，拖拽设计、样例数据、预览与直打</li></ul><h3 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to “AI”">​</a></h3><ul><li><strong>新增</strong> AI 提供商（OpenAI 兼容，密钥加密，设缺省，测试连接；厂商不是 OpenAI 时端点必填）、提示词、知识库、助手</li><li><strong>新增</strong> 助手在聊天里流式回复（输出时显示光标），按知识库回答，以调用方身份调用勾选的工具，没有权限时被拒；回复按 Markdown 显示，图片语法只留成链接</li><li><strong>新增</strong> 平台与各租户各自维护知识，互不可见；检索失败即回复失败，不退化成纯模型回答；还被引用的提示词与提供商不能删除；最大输出与温度生效</li></ul><h3 id="壳层与通用体验" tabindex="-1">壳层与通用体验 <a class="header-anchor" href="#壳层与通用体验" aria-label="Permalink to “壳层与通用体验”">​</a></h3><ul><li><strong>新增</strong> 前端壳层：亮暗、主题色预设、Material You 动态取色、布局、密度、水印、多标签页、收藏、全局搜索、通知中心、分屏、锁屏；布局、标签页、列表页与工作台带过渡</li><li><strong>新增</strong> 偏好、收藏与页面设置（列设置、搜索设置、个人视图、看板布局）跨端同步，同一账号在别的设备上改了，已打开的页面实时生效</li><li><strong>新增</strong> SchemaPage：组合搜索、个人视图、列设置、多列排序、树表、行速览、导出与导入</li><li><strong>新增</strong> 工作台：各包登记的指标、图表与列表小组件，看板布局跨端同步，「我的待办」</li><li><strong>新增</strong> 关于页与内置的「帮助中心」目录（种子只首写，之后可改、可停用、可删）；时区目录用浏览器 <code>Intl</code></li></ul><h3 id="配置与运维" tabindex="-1">配置与运维 <a class="header-anchor" href="#配置与运维" aria-label="Permalink to “配置与运维”">​</a></h3><ul><li><strong>新增</strong> 配了 Redis（绑定 <code>cache</code>）即装分布式缓存，配了 RabbitMQ（绑定 <code>queue</code>）即装消息代理，不配仍是单机零外部依赖；配了连不上启动即失败</li><li><strong>新增</strong> 出站地址策略：向用户填的地址发请求时，缺省只能连公网地址（<code>XiHan:Security:Outbound</code>）。工作流 <code>Http</code> 活动、群机器人 Webhook、SMTP 服务器、AI 提供商、第三方登录、S3 兼容存储与代码生成的外部数据源都受约束。<strong>自建 MinIO、内网 Webhook、内网 SMTP 中继、内网业务库、流程调内网服务、本机模型端点要在这一节放行</strong>；Telegram 的 <code>Network.BaseUrl</code> 改成自建地址时，主机要在 <code>AllowedHosts</code> 放行</li><li><strong>新增</strong> 平台库可以配从库（<code>BasicApp:Database:Replicas</code>），从库健康探测缺省开；授予、租户目录与决定授权的读取都读主库（见<a href="./deployment#读写分离">部署</a>）</li><li><strong>新增</strong> SQL 日志、错误日志与慢 SQL 可配；SignalR 的保活、超时与消息大小可配；转发头（缺省只信本机回环）与跨域（不配即不启用）可配</li><li><strong>新增</strong> 数据库宕了，<code>persistence.sqlsugar.database</code> 与运行时数据源的健康项如实报失败（<code>KERNEL_UNAVAILABLE_005</code>）；代码生成的数据源连接测试有上限，缺省 15 秒（<code>XiHan:Persistence:DataSources:HealthProbeIntervalSeconds</code>）</li><li><strong>新增</strong> <code>docker-compose.yml</code> 一键起 PostgreSQL、后端与前端，<code>init</code> 服务先执行表结构升级与种子（见<a href="./deployment#容器-docker-compose">部署</a>）</li></ul>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};